3	/**
4	 * Compare grammar-generated SQL with native MySql execution and check ZTD isolation.
5	 *
6	 * Usage: vendor/bin/php-fuzzer fuzz fuzz/fuzz_behavior.php /path/to/corpus/ --timeout=60
7	 * Copy sql-faker/seeds/mysql/mysql-8.4.7/* into that corpus to replay grammar seeds.
8	 * Default mode uses the exact sql-faker byte decoder and unconstrained statement root.
9	 * ZTD_FUZZ_FIXTURES=1 constrains DML table/column roles through Plan for populated fixtures;
10	 * use a separate corpus for this mode. SQLFAKER_COVERAGE=0 disables coverage recording.
11	 * Native errors are compared with ZTD rejections, never discarded by an allowlist.
12	 */
13	
14	declare(strict_types=1);
15	
16	use Container\MySql84Container;
17	use Faker\Factory;
18	use Fuzz\Target\BehaviorTarget;
19	use SqlFaker\Generation\Choice\BytePlanCompiler;
20	use SqlFaker\Generation\Coverage\GrammarCoverage;
21	use SqlFaker\Generation\Plan\GenerationPlan;
22	use SqlFaker\Generation\Plan\LexemeConstraint;
23	use SqlFaker\Generation\Plan\ProductionPattern;
24	use SqlFaker\Generation\Plan\RulePlan;
25	use SqlFaker\MySql\MySqlProvider;
26	use Testcontainers\Testcontainers;
27	
28	/**
29	 * Register before Testcontainers so the PHP-Fuzzer alarm cannot interrupt teardown.
30	 */
31	register_shutdown_function(static function (): void {
32	    if (function_exists('pcntl_alarm')) {
33	        pcntl_alarm(0);
34	    }
35	});
36	$instance = Testcontainers::run(MySql84Container::class);
37	$host = str_replace('localhost', '127.0.0.1', $instance->getHost());
38	$port = $instance->getMappedPort(3306);
39	$target = new BehaviorTarget("mysql:host={$host};port={$port}");
40	
41	$fixtures = getenv('ZTD_FUZZ_FIXTURES') === '1';
42	$coverage = getenv('SQLFAKER_COVERAGE') === '0' ? null : new GrammarCoverage(__DIR__ . '/coverage/' . ($fixtures ? 'fixtures' : 'behavior'));
43	$provider = new MySqlProvider(Factory::create(), 'mysql-8.4.7', $coverage);
44	$planner = $provider->planner();
45	$constraints = GenerationPlan::fromRule('simple_statement_or_begin')->requiringNonEmpty();
46	if ($fixtures) {
47	    $constraints = $constraints
48	        ->withRule('simple_statement_or_begin', RulePlan::any()->allowing(ProductionPattern::exactly('simple_statement')))
49	        ->withRule('simple_statement', RulePlan::any()->allowing(ProductionPattern::anyOf(
50	            ProductionPattern::exactly('select_stmt'),
51	            ProductionPattern::exactly('insert_stmt'),
52	            ProductionPattern::exactly('update_stmt'),
53	            ProductionPattern::exactly('delete_stmt'),
54	        )))
55	        ->withRule('ident', RulePlan::any()->allowing(ProductionPattern::exactly('IDENT_sys')))
56	        ->withRule('IDENT_sys', RulePlan::any()->allowing(ProductionPattern::exactly('IDENT')))
57	        ->withRule('table_ident', RulePlan::any()->allowing(ProductionPattern::exactly('ident'))
58	            ->withLexeme('IDENT', LexemeConstraint::oneOf('items')))
59	        ->withRule('simple_ident', RulePlan::any()->allowing(ProductionPattern::exactly('ident'))
60	            ->withLexeme('IDENT', LexemeConstraint::oneOf('id', 'value', 'label')));
61	    $constraints = $constraints->withExpansionBudget(256);
62	}
63	
64	/**
65	 * @var PhpFuzzer\Config $config
66	 */
67	$config->setAllowedExceptions([]);
68	$config->setMaxLen(80004);
69	$config->setTarget(static function (string $input) use ($provider, $planner, $constraints, $target): void {
70	    $plan = (new BytePlanCompiler())->compile($input, $planner, $constraints);
71	    $target->verify($provider->generate($plan), $input);
72	});
