27	/**
28	 * Compares native SQL with the platform session, independently of production adapters.
29	 * Checks rows (including multiplicity and NULL), affected counts, rejection reasons,
30	 * subsequent table reads, and physical isolation, including on rejected statements.
31	 * Unordered row bags are compared; result ordering is outside this target's contract.
32	 */
33	final class BehaviorTarget implements ConnectionInterface
34	{
35	    private PDO $physical;
36	
37	    /**
38	     * Connect only to the disposable server owned by the entrypoint.
39	
40	     */
41	    public function __construct(private readonly string $dsn)
42	    {
43	    }
44	
45	    /**
46	     * Reset a private database and use a user with privileges on that database only.
47	
48	     */
49	    public function database(string $side): PDO
50	    {
51	        $name = 'ztd_fuzz_' . getmypid();
52	        $options = [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_EMULATE_PREPARES => false];
53	        try {
54	            $root = new PDO($this->dsn, 'root', 'root', $options);
55	            $root->exec("DROP DATABASE IF EXISTS `$name`");
56	            $root->exec("CREATE DATABASE `$name`");
57	            $root->exec("DROP USER IF EXISTS '$name'@'%'");
58	            $root->exec("CREATE USER '$name'@'%' IDENTIFIED BY '$name'");
59	            $root->exec("GRANT ALL ON `$name`.* TO '$name'@'%'");
60	            $pdo = new PDO($this->dsn . ';dbname=' . $name, $name, $name, $options);
61	            $pdo->exec('SET SESSION max_execution_time = 2000');
62	            $pdo->exec('SET SESSION innodb_lock_wait_timeout = 2');
63	            $pdo->exec('CREATE TABLE items (id INTEGER PRIMARY KEY NOT NULL, value INTEGER, label VARCHAR(80))');
64	            if ($side === 'physical') {
65	                $pdo->exec("INSERT INTO items VALUES (9999, 9999, 'physical-only')");
66	            }
67	            return $pdo;
68	        } catch (PDOException $failure) {
69	            fwrite(STDERR, "MySQL setup failed: {$failure->getMessage()}\n");
70	            exit(2);
71	        }
72	    }
73	
74	    /**
75	     * Run a grammar statement against equal fixtures and compare observable effects.
76	     * Native execution is repeated on a fresh database to identify volatile SQL.
77	     * All three runs reuse the same catalog and user names, avoiding environment mismatches.
78	     * No SQL exception is accepted merely because both executions threw something.
79	     *
80	     * @throws Error When ZTD differs from the native server
81	     * @throws PDOException When reading a database fails
82	     * @throws DatabaseException When fixture setup through ZTD fails
83	     */
84	    public function verify(string $sql, string $input): void
85	    {
86	
87	        unset($this->physical);
88	        $fixtures = "INSERT INTO items VALUES (1, -2, 'first'), (2, 0, NULL), (3, 7, 'O''Brien')";
89	        $native = $this->database('reference');
90	        $native->exec($fixtures);
91	        $native->exec('UPDATE items SET value = value WHERE 0 = 1');
92	        $expected = $this->native($native, $sql);
93	        $state = $this->tables($native);
94	        $native = null;
95	        $native = $this->database('reference');
96	        $native->exec($fixtures);
97	        $native->exec('UPDATE items SET value = value WHERE 0 = 1');
98	        $stable = $this->native($native, $sql) === $expected && $this->tables($native) === $state;
99	        $native = null;
100	        $this->physical = $this->database('physical');
101	        $before = $this->snapshot($this->physical);
102	        $context = 'Input (hex): ' . bin2hex($input) . "\nSQL: {$sql}";
103	        try {
104	            $session = (new MySqlSessionFactory())->create($this, new ZtdConfig(UnsupportedSqlBehavior::Exception, UnknownSchemaBehavior::Exception));
105	            $this->execute($session, $fixtures);
106	            $this->physical->exec('UPDATE items SET value = value WHERE 0 = 1');
107	            $actual = $this->virtual($session, $sql);
108	            if (!$stable) {
109	                return;
110	            }
111	            if ($expected !== $actual) {
112	                throw new Error($context . "\nNative and ZTD outcomes differ.\nExpected: " . var_export($expected, true) . "\nActual: " . var_export($actual, true));
113	            }
114	            foreach (array_unique(['items', ...array_keys($state)]) as $table) {
115	                $definition = $session->tableDefinition($table);
116	                $observed = $definition === null ? null : [
117	                    'columns' => $definition->columns,
118	                    'rows' => $this->virtual($session, 'SELECT * FROM ' . $this->quote($table)),
119	                ];
120	                if (($state[$table] ?? null) !== $observed) {
121	                    throw new Error($context . "\nVirtual table differs after the statement: " . $table . "\nExpected: " . var_export($state[$table] ?? null, true) . "\nActual: " . var_export($observed, true));
122	                }
123	            }
124	        } finally {
125	
126	            if ($before !== $this->snapshot($this->physical)) {
127	                throw new Error("The physical database changed.\n" . $context);
128	            }
129	        }
130	    }
131	
132	    /**
133	     * Execute through core, including transaction statements and returning writes.
134	     * @return array<mixed>
135	     * @throws PDOException When native result-select SQL fails
136	     * @throws DatabaseException When ZTD rejects a statement
137	     * @throws Error When ZTD silently skips a statement
138	     */
139	    public function execute(Session $session, string $sql): array
140	    {
141	        $transaction = $session->transactionStatement($sql);
142	        if ($transaction !== null) {
143	            $session->applyTransactionStatement($transaction);
144	            return ['ok', 0];
145	        }
146	        $plan = $session->rewrite($sql);
147	        if ($plan->kind() === QueryKind::SKIPPED) {
148	            throw new Error('ZTD silently skipped: ' . $sql);
149	        }
150	        $result = $session->processExecutedStatement($plan, $this->query($plan->sql()));
151	        return ['ok', $result->hasResultSet() ? $this->rows($result->fetchAll()) : $result->rowCount()];
152	    }
153	
154	    /**
155	     * Capture declared database rejections, leaving programming failures to PHP-Fuzzer.
156	     * @return array<mixed>
157	     * @throws Error When the session silently skips SQL
158	     */
159	    public function virtual(Session $session, string $sql): array
160	    {
161	        try {
162	            return $this->execute($session, $sql);
163	        } catch (PDOException|DatabaseException $failure) {
164	            return ['error', $this->rejection($failure)];
165	        }
166	    }
167	
168	    /**
169	     * Use the native server as the outcome oracle, including for invalid statements.
170	     * @return array<mixed>
171	     */
172	    public function native(PDO $pdo, string $sql): array
173	    {
174	        try {
175	            $statement = $pdo->query($sql);
176	            if ($statement === false) {
177	                fwrite(STDERR, "PDO::query failed without an exception.\n");
178	                exit(2);
179	            }
180	            $answer = ['ok', $statement->columnCount() > 0 ? $this->rows($statement->fetchAll(PDO::FETCH_ASSOC)) : $statement->rowCount()];
181	            $statement->closeCursor();
182	            return $answer;
183	        } catch (PDOException $failure) {
184	            return ['error', $this->rejection($failure)];
185	        }
186	    }
187	
188	    /**
189	     * Compare narrowly identified domain failures; every other native error keeps its identity.
190	     * Unknown ZTD rejections retain their exception class and message and cannot match native errors.
191	     */
192	    public function rejection(Throwable $failure): string
193	    {
194	        for ($cause = $failure; $cause !== null; $cause = $cause->getPrevious()) {
195	            if ($cause instanceof DuplicateKeyException) {
196	                return 'unique';
197	            }
198	            if ($cause instanceof NotNullViolationException) {
199	                return 'not-null';
200	            }
201	            if ($cause instanceof UnknownSchemaException) {
202	                return 'missing-table';
203	            }
204	            if ($cause instanceof PDOException) {
205	                $state = $cause->errorInfo[0] ?? '';
206	                $code = $cause->errorInfo[1] ?? 0;
207	                $message = $cause->errorInfo[2] ?? $cause->getMessage();
208	                $state = is_string($state) ? $state : '';
209	                $message = is_string($message) ? $message : $cause->getMessage();
210	                if (str_starts_with($state, '08') || str_starts_with($state, '57P0') || in_array($code, [2002, 2006, 2013], true)) {
211	                    fwrite(STDERR, 'Database connection failed: ' . $message . "\n");
212	                    exit(2);
213	                }
214	                if ($state === '23505' || $code === 1062 || str_contains($message, 'UNIQUE constraint failed:')) {
215	                    return 'unique';
216	                }
217	                if ($state === '23502' || $code === 1048 || str_contains($message, 'NOT NULL constraint failed:')) {
218	                    return 'not-null';
219	                }
220	                if ($state === '42P01' || $code === 1146 || str_starts_with($message, 'no such table:')) {
221	                    return 'missing-table';
222	                }
223	                return $state . ':' . (is_scalar($code) ? (string) $code : '') . ':' . $message;
224	            }
225	        }
226	        return $failure::class . ':' . $failure->getMessage();
227	    }
228	
229	    /**
230	     * Preserve driver values, column names, NULLs and duplicates, ignoring only row order.
231	     * @param array<mixed> $rows
232	     * @return list<string>
233	     */
234	    public function rows(array $rows): array
235	    {
236	        $rows = array_map(serialize(...), $rows);
237	        sort($rows, SORT_STRING);
238	        return $rows;
239	    }
240	
241	    /**
242	     * Inspect every current user table, including tables created by the generated statement.
243	     * @return array<string, array{columns: list<string>, rows: array<mixed>}>
244	     * @throws PDOException When catalog inspection fails
245	     */
246	    public function tables(PDO $pdo): array
247	    {
248	        $tables = [];
249	        $catalog = $pdo->query("SELECT table_name FROM information_schema.tables WHERE table_schema = DATABASE() AND table_type = 'BASE TABLE' ORDER BY table_name");
250	        if ($catalog === false) {
251	            fwrite(STDERR, "Cannot inspect the database catalog.\n");
252	            exit(2);
253	        }
254	        foreach ($catalog->fetchAll(PDO::FETCH_COLUMN) as $name) {
255	            if (!is_string($name)) {
256	                continue;
257	            }
258	            $statement = $pdo->query('SELECT * FROM ' . $this->quote($name));
259	            if ($statement === false) {
260	                fwrite(STDERR, "Cannot inspect table rows.\n");
261	                exit(2);
262	            }
263	            $columns = [];
264	            for ($index = 0; $index < $statement->columnCount(); ++$index) {
265	                $metadata = $statement->getColumnMeta($index);
266	                if ($metadata === false) {
267	                    fwrite(STDERR, "Cannot inspect result metadata.\n");
268	                    exit(2);
269	                }
270	                $columns[] = $metadata['name'];
271	            }
272	            $tables[$name] = ['columns' => $columns, 'rows' => ['ok', $this->rows($statement->fetchAll(PDO::FETCH_ASSOC))]];
273	        }
274	        ksort($tables);
275	        return $tables;
276	    }
277	
278	    /**
279	     * Include catalog definitions so that a physical DDL change is also a finding.
280	     * @return array<mixed>
281	     * @throws PDOException When snapshot inspection fails
282	     */
283	    public function snapshot(PDO $pdo): array
284	    {
285	        $tables = $this->tables($pdo);
286	        $definitions = [];
287	        foreach (array_keys($tables) as $table) {
288	            $definitions[$table] = $this->native($pdo, 'SHOW CREATE TABLE ' . $this->quote($table));
289	        }
290	        return [$tables, $definitions,
291	            $this->native($pdo, 'SELECT table_name, view_definition FROM information_schema.views WHERE table_schema = DATABASE()'),
292	            $this->native($pdo, 'SELECT trigger_name, action_statement FROM information_schema.triggers WHERE trigger_schema = DATABASE()'),
293	            $this->native($pdo, 'SELECT routine_name, routine_definition FROM information_schema.routines WHERE routine_schema = DATABASE()'),
294	        ];
295	    }
296	
297	    /**
298	     * Quote catalog identifiers without interpreting generated SQL.
299	
300	     */
301	    public function quote(string $name): string
302	    {
303	        return '`' . str_replace('`', '`' . '`', $name) . '`';
304	    }
305	
306	    /**
307	     * Minimal native bridge for the platform contract; no production adapter is involved.
308	     * @throws PDOException When result-select SQL fails on the server
309	     * @throws Error When the driver silently fails
310	     */
311	    public function query(string $sql): StatementInterface
312	    {
313	        $statement = $this->physical->query($sql);
314	        if ($statement === false) {
315	            throw new Error('Native result-select execution silently failed.');
316	        }
317	        return new class ($statement) implements StatementInterface {
318	            /**
319	             * Wrap the native result.
320	             */
321	            public function __construct(private readonly PDOStatement $statement)
322	            {
323	            }
324	
325	            /**
326	             * Execute the native statement.
327	
328	             */
329	            public function execute(?array $params = null): bool
330	            {
331	                return $this->statement->execute($params);
332	            }
333	
334	            /**
335	             * Fetch native rows without coercing driver values.
336	             * @throws Error When a native row has an unexpected shape
337	             */
338	            public function fetchAll(): array
339	            {
340	                $rows = [];
341	                foreach ($this->statement->fetchAll(PDO::FETCH_ASSOC) as $row) {
342	                    if (!is_array($row)) {
343	                        throw new Error('The driver did not return an associative row.');
344	                    }
345	                    $values = [];
346	                    foreach ($row as $column => $value) {
347	                        $values[(string) $column] = $value;
348	                    }
349	                    $rows[] = $values;
350	                }
351	                return $rows;
352	            }
353	
354	            /**
355	             * Resolve native column metadata using the platform contract.
356	             * @throws Error When metadata is unavailable
357	             */
358	            public function resultColumns(ResultColumnTypeResolver $typeResolver): array
359	            {
360	                $columns = [];
361	                for ($index = 0; $index < $this->statement->columnCount(); ++$index) {
362	                    $metadata = $this->statement->getColumnMeta($index);
363	                    if ($metadata === false) {
364	                        throw new Error('The driver omitted result metadata.');
365	                    }
366	                    $columns[] = new ResultColumn($metadata['name'], $typeResolver->resolve($metadata));
367	                }
368	                return $columns;
369	            }
370	
371	            /**
372	             * Return the native affected count.
373	
374	             */
375	            public function rowCount(): int
376	            {
377	                return $this->statement->rowCount();
378	            }
379	        };
380	    }
381	}
