5	namespace Fuzz\Target;
6	
7	use Error;
8	use LogicException;
9	use Tests\Fake\FakeConnection;
10	use Tests\Fake\FakeSqlRewriter;
11	use ZtdQuery\Config\ZtdConfig;
12	use ZtdQuery\Connection\Exception\DatabaseException;
13	use ZtdQuery\Connection\ResultSet;
14	use ZtdQuery\Exception\DuplicateKeyException;
15	use ZtdQuery\Exception\NotNullViolationException;
16	use ZtdQuery\ResultSelectRunner;
17	use ZtdQuery\Schema\TableDefinition;
18	use ZtdQuery\Schema\TableDefinitionRegistry;
19	use ZtdQuery\Session;
20	use ZtdQuery\Shadow\Mutation\Row\DeleteMutation;
21	use ZtdQuery\Shadow\Mutation\Row\InsertMutation;
22	use ZtdQuery\Shadow\Mutation\Row\UpdateMutation;
23	use ZtdQuery\Shadow\Mutation\Table\CreateTableMutation;
24	use ZtdQuery\Shadow\Mutation\Table\DropTableMutation;
25	use ZtdQuery\Shadow\ShadowStore;
26	use ZtdQuery\Shadow\ShadowTransactions;
27	
28	/**
29	 * Compares two isolated core sessions with independent array models.
30	 * Four bytes select session/operation, table, identity, and opaque value/savepoint.
31	 */
32	final class SessionTarget
33	{
34	    /**
35	     * Actual virtual rows owned by this session.
36	     */
37	    private readonly ShadowStore $store;
38	    /**
39	     * Actual virtual schema owned by this session.
40	     */
41	    private readonly TableDefinitionRegistry $registry;
42	    /**
43	     * Core session under test.
44	     */
45	    private readonly Session $session;
46	    /**
47	     * Recording physical connection, which must receive no queries.
48	     */
49	    private readonly FakeConnection $connection;
50	
51	    /**
52	     * Create one isolated core session with a recording connection.
53	     */
54	    public function __construct()
55	    {
56	        $this->store = new ShadowStore();
57	        $this->registry = new TableDefinitionRegistry();
58	        $this->connection = new FakeConnection();
59	        foreach (['items', 'other'] as $table) {
60	            $this->store->set($table, []);
61	            $this->registry->register($table, self::definition());
62	        }
63	        $this->session = new Session(new FakeSqlRewriter($this->store, $this->registry), $this->store, new ResultSelectRunner(), ZtdConfig::default(), $this->connection, new ShadowTransactions($this->store, $this->registry), $this->registry);
64	    }
65	
66	    /**
67	     * Return the row contract used by core mutation operations.
68	     */
69	    public static function definition(): TableDefinition
70	    {
71	        return new TableDefinition(['id', 'value'], ['id' => 'INTEGER', 'value' => 'TEXT'], ['id'], ['id'], []);
72	    }
73	
74	    /**
75	     * Apply one mutation or transaction through the core session.
76	     * @param int|string|null|array{opaque: int} $value
77	     * @throws DatabaseException
78	     * @throws LogicException
79	     */
80	    public function apply(int $operation, string $table, int $id, int|string|array|null $value, string $name): void
81	    {
82	        if ($operation >= 3 && $operation <= 8) {
83	            match ($operation) {
84	                3 => $this->session->beginTransaction(),
85	                4 => $this->session->commitTransaction(),
86	                5 => $this->session->rollBackTransaction(),
87	                6 => $this->session->transactions()->savepoint($name),
88	                7 => $this->session->transactions()->rollBackTo($name),
89	                8 => $this->session->transactions()->release($name),
90	            };
91	            return;
92	        }
93	        $rows = [['id' => $id, 'value' => $value]];
94	        if ($operation === 11 || $operation === 12) {
95	            $rows = [['id' => 1000 + $id, 'value' => $value], ['id' => $operation === 11 ? 1000 + $id : null, 'value' => $value]];
96	        }
97	        $mutation = match ($operation) {
98	            0, 11, 12 => new InsertMutation($table, ['id'], tableDefinition: self::definition(), validateConstraints: true),
99	            1 => new UpdateMutation($table, ['id'], self::definition(), validateConstraints: true),
100	            2 => new DeleteMutation($table, ['id']),
101	            9 => new CreateTableMutation('temporary', self::definition(), $this->registry, 'CREATE', true),
102	            10 => new DropTableMutation('temporary', $this->registry, 'DROP', true),
103	            default => throw new LogicException('Unrecognized core operation.'),
104	        };
105	        $this->session->applyShadow($mutation, new ResultSet($rows, []), 'fuzz operation');
106	    }
107	
108	    /**
109	     * @var array<string, array<int, array{id: int, value: int|string|null|array{opaque: int}}>>
110	     */
111	    private array $tables = ['items' => [], 'other' => []];
112	    /**
113	     * @var list<array{name: string|null, tables: array<string, array<int, array{id: int, value: int|string|null|array{opaque: int}}>>}>
114	     */
115	    private array $checkpoints = [];
116	
117	    /**
118	     * Advance the plain-array model or return the required rejection category.
119	     * @param int|string|null|array{opaque: int} $value
120	     */
121	    public function modelApply(int $operation, string $table, int $id, int|string|array|null $value, string $name): ?string
