150	            $this->checkpoints[] = ['name' => null, 'tables' => $this->tables];
151	        } elseif ($operation === 4) {
152	            $this->checkpoints = [];
153	        } elseif ($operation === 5 && $this->checkpoints !== []) {
154	            $this->tables = $this->checkpoints[0]['tables'];
155	            $this->checkpoints = [];
156	        } elseif ($operation >= 6) {
