17	 *
18	 * MySQL cannot undo most statements, and the server may be shared with other test runs,
19	 * so statements run as a user of their own with rights on a database of their own only:
20	 * the server denies everything that would reach beyond it, such as SHUTDOWN, KILL of other
21	 * sessions or SET GLOBAL, and the database is dropped and created again before every
22	 * statement, so both texts meet the same empty schema. A statement that ends the
23	 * connection, or changes the fuzz user's own password, is followed by a fresh user and
24	 * connection. A mismatch is confirmed by running the original once more, so a statement
25	 * that reads the clock is not reported.
26	 */
27	final class MySqlEquivalence
28	{
29	    /**
30	     * The user and database the statements run in, recreated whenever the connection is replaced.
31	     */
32	    public const USER = 'sql_formatter_fuzz';
33	
34	    /**
35	     * Client and server errors after which the connection is replaced rather than compared:
36	     * the server went away, the connection was killed, or the fuzz user cannot log in any more.
37	     *
38	     * @var list<int>
39	     */
40	    public const CONNECTION_ERRORS = [1040, 1045, 1820, 2002, 2006, 2013, 3118];
41	
42	    private PDO $pdo;
43	
44	    /**
45	     * @param string $dsn PDO data source name of the MySQL server under test, without a database
46	     * @param string $rootPassword Password of the root account that creates the fuzz user
47	     * @param Formatter $formatter The formatter under test
48	     * @param Style $style The layout preset in use, for findings
49	     * @param string $grammarVersion Grammar version that produced the statement, e.g. "mysql-8.4.7"
50	     */
51	    public function __construct(
