30	    /**
31	     * Analyzes the input and checks that the catalog it produced is coherent.
32	     *
33	     * @throws Error When the catalog contradicts itself
34	     */
35	    public function __invoke(string $input): void
36	    {
37	        $catalog = $this->analyzer->analyzeSource(['fuzz.php' => '<?php ' . $input]);
38	
39	        foreach ($catalog as $entry) {
40	            if ($entry->id === '' || $entry->site->file !== 'fuzz.php') {
41	                throw new Error('Catalogued a statement without an identity; input=' . bin2hex($input));
42	            }
43	            if ($entry->isExact() && str_contains($entry->sql(), '{$}')) {
44	                throw new Error('A resolved statement still shows a gap; input=' . bin2hex($input));
45	            }
46	        }
47	
48	        if ($catalog->count() > 0 && $catalog->problems() !== []) {
49	            throw new Error('Reported both statements and a parse failure; input=' . bin2hex($input));
50	        }
51	    }
